var i=`0426-gravlax`;var a=`world-0426`;var o=`SE`;var s=`northern-europe`;var r=4;var t=2898;var l={en:`Gravlax`,ua:`Гравлакс`};var d={en:`A traditional dish from Sweden, centered on salmon, sea salt, dill, lemon. A measured home-kitchen version organized by cooking step. Cured salmon is not cooked: use only fish supplied as suitable for raw consumption by a reputable vendor; curing does not eliminate foodborne hazards. Not suitable for vulnerable diners.`,ua:`Традиційна страва кухні країни Швеція. Основні складники: лосось, морська сіль, кріп, лимон. Домашній варіант із кількостями продуктів за етапами приготування. Слабосолений лосось не проходить термообробку: беріть лише рибу, придатну для сирого споживання, від перевіреного продавця. Посол не усуває всіх ризиків; не подавайте вразливим групам.`};var u=[{en:`Use salmon sold for raw consumption. Remove pin bones, mix salt, sugar, dill and pepper and coat the fillet evenly. Keep the fish cold.`,ua:`Використовуйте лише лосося, призначеного для сирого споживання. Видаліть кістки, змішайте сіль, цукор, кріп і перець та покрийте філе, не порушуючи холодового режиму.`,t:[`mixing`],m:7,i:[[`salmon`,650,`g`],[`sea-salt`,65,`g`],[`white-granulated-sugar`,55,`g`],[`dill`,55,`g`],[`ground-black-pepper`,4,`g`]]},{en:`Cover and cure the fish in the refrigerator at or below 4°C for 48 hours; turn it occasionally. Curing alone does not make ordinary raw fish safe.`,ua:`Накрийте й витримуйте рибу в холодильнику за температури не вище 4°C протягом 48 годин, періодично перевертаючи. Сам посол не робить звичайну сиру рибу безпечною.`,t:[`dry-curing`],m:2880,i:[]},{en:`Brush away the excess cure and slice the chilled salmon thinly with a clean knife.`,ua:`Зніміть надлишок посолочної суміші й наріжте охолодженого лосося тонкими скибками чистим ножем.`,t:[`chopping`,`dicing`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon`,1,`pcs`],[`dijon-mustard`,20,`g`]]}];var g={slug:i,id:a,country:`SE`,region:s,servings:4,minutes:t,title:l,text:d,steps:u};export{o as country,g as default,a as id,t as minutes,s as region,r as servings,i as slug,u as steps,d as text,l as title};